func (d dbCallDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*ldspec.DbCall, err error) {
	buf := make([]*ldspec.DbCall, 0, batchSize)
	err = d.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

